  'about.bookshopLeadIn': "हमनी के किताब के दुकान चलावे वाला उहे छोट व्यवसाय द्वारा बनावल गइल:",
  "about.eyebrow": "Luminous StockHaven के बारे में",
  "about.pageTitle": "Luminous StockHaven — हमरा बारे में",
  "about.founderHeading": "📖 संस्थापक के बारे में",
  "about.founder.p1": "नमस्कार, हम कॉन्सेप्सियॉन हईं, Luminous StockHaven के संस्थापक।",
  "about.founder.p2": "हम कवनो बड़ टेक कंपनी से ना अइनी, आ हम कवनो कॉर्पोरेट दफ्तर में ना बइठेनी। हम एगो छोट खुदरा दुकानदार हईं, बिल्कुल रउरा नियर। हम पाँच गो ई-कॉमर्स दुकान चलावेनी, जवन किताब आ किताब-प्रेमी लोग खातिर हाथ से बनावल सामान में खास बा।\nबहुत सारा स्वतंत्र खुदरा बेचेवाला लोग नियर, हम ओह मोड़ पर पहुँच गइल रहनी जहाँ कई जगह के इन्वेंटरी संभारल, प्रकाशक लोग के ISBN के अपना हाथ से बनावल SKU के साथ-साथ ट्रैक कइल, आ अनाड़ी स्प्रेडशीट से सप्लायर ऑर्डर संभारल मुश्किल हो गइल रहे। जब हम मदद खातिर कवनो ऐप खोजनी, त हम छह गो अलग विकल्प आजमवनी। हर एक या त पूरा अधूरा रहे, या अविश्वसनीय रूप से भ्रमित करे वाला रहे, या लूटे वाला रहे — बुनियादी औजार खातिर महीना के सैकड़न डॉलर वसूलत रहे।",
  "about.founder.p3": "स्वतंत्र रचनाकार लोग के शोषण करे वाला उद्योग से निराश होके, हम अपन समाधान खुद बनावे के फैसला कइनी। हम Luminous StockHaven जरूरत से बनवनी, ताकि हम अपन व्यवसाय साफ-सुथरा, कुशल आ पूरा मानसिक शांति के साथ चला सकीं।",
  "about.founder.p4": "हम एह प्लेटफ़ॉर्म के ईमानदार आ किफ़ायती दाम पर जनता खातिर खोले के फैसला कइनी, काहे कि हर छोट दुकानदार अइसन औजार के हकदार बा जवन सचमुच काम करे, अपना कमाई के जोखिम में डाले बिना। हम स्वतंत्र रूप से मालिकाना वाला बानी, अपना समुदाय के पूरा ताकत से रक्षा करेनी, आ एगो खुदरा बेचेवाला द्वारा, खुदरा बेचेवाला लोग खातिर बनावल गइल बानी।",
  "notice.ariaLabel": "ट्रेडमार्क आ कॉपीराइट सूचना",
  "notice.heading": "🛡️ खुदरा बेचेवाला लोग खातिर बनल, कॉर्पोरेट गिद्ध लोग खातिर अनमोल",
  "notice.intro": "हम एह ऐप के एह से बनवनी कि हम 5 गो दुकान चलावेनी आ सैकड़न डॉलर के भ्रमित करे वाला सॉफ़्टवेयर से ठगाए से थाक गइल रहनी। एह ऐप स्वतंत्र कलाकार, कारीगर, किताब बेचेवाला आ स्थानीय दुकानन के रक्षा खातिर बनावल गइल बा।",
  "notice.legalHeading": "प्रतिस्पर्धी आ नकलची लोग खातिर कानूनी सूचना:",
  "notice.legalBody": "हम बाजार पर सक्रिय रूप से नजर रखेनी। हमरा प्लेटफ़ॉर्म के डेटा निकालल, हमरा मालिकाना कार्यप्रणाली के नकल कइल, या हमरा बौद्धिक संपदा के उल्लंघन करे के कवनो कोशिश तुरंत आ आक्रामक कानूनी कार्रवाई से मिली।",
  "notice.acquisitionHeading": "अधिग्रहण कंपनी आ दलाल लोग खातिर:",
  "notice.acquisitionBody": "हमरा के ईमेल मत करीं। हमरा के संदेश मत भेजीं। हमरा के 'रणनीतिक निकास' के प्रस्ताव मत दीं। रउरा हजारन, लाखन, करोड़न या खरबन के पेशकश कर सकत बानी — जवाब बा ना। रउरा एह ऐप के सिर्फ एह से ना खरीदब कि हमरा साथी व्यापारी लोग खातिर दाम बढ़ा सकीं। हर अनचाहा अधिग्रहण ईमेल तुरंत स्पैम के रूप में चिह्नित कइल जाई, आ रउरा डोमेन हमरा प्लेटफ़ॉर्म से स्थायी रूप से रोक दिहल जाई। अपन मेहनत बचाईं।",
