  "upgrade.pastDueBody": "राउर पिछला भुगतान पूरा ना भइल, एह से ई सदस्यता बकाया बा। असफल भुगतान से 14 दिन तक रउरा पूरा उपयोग मिलत रही, जब तक रउरा ओके ठीक ना करीं। अगर ठीक ना भइल, त सदस्यता रद्द हो जाई, कार्यक्षेत्र 15 दिन खातिर खाली देखे योग्य हो जाई, आ फिर खाता आ ओकर सगरी जानकारी हटा दिहल जाई। हटावे से पहिले कवनो समय भुगतान कइला से सगरी वापस आ जाई। नीचे आपन भुगतान विधि अपडेट करीं। अगर मदद चाहीं, त ईमेल करीं",
