  "upgrade.upgradeNeverRestartsTrial": "अपग्रेड करे से कबो राउर मुफ्त ट्रायल फेर से शुरू ना होई।",
  "upgrade.trialHistoryNote": "अगर रउआ Essentials खातिर भुगतान कर रहल बानी आ Business में जानी, त रउआ उहे ग्राहक खाता आ ट्रायल इतिहास रखब। Business में अतिरिक्त सात दिन के ट्रायल शामिल नइखे। अगर रउआ आपन मूल ट्रायल चलत घरी अपग्रेड करीं, त ओकर मूल समाप्ति तारीख रीसेट ना होई।",
  "upgrade.providerConfirmNote": "प्लान बदले खातिर बिलिंग प्रदाता से पुष्टि के जरूरत होला। कवनो कीमत अंतर, प्रोरेशन, आ प्रभावी तारीख बदलाव के मंजूरी देवे से पहिले देखावे के चाहीं। अपग्रेड से कबो दू गो एक साथ सब्सक्रिप्शन ना बने के चाहीं।",
  "upgrade.chargedThroughProviderNote": "प्लान बदलाव के चार्ज बिलिंग प्रदाता से होला। रउआ आपन सब्सक्रिप्शन एह पेज से रद्द कर सकत बानी, आपन वर्तमान प्लान के नीचे Cancel Subscription बटन से, भा Settings से। रद्द करे से राउर भुगतान अवधि के अंत में भविष्य के नवीनीकरण रुक जाई; ई कबो राउर पहुँच एक बेर में खत्म ना करेला। मौजूदा मुफ्त वर्कस्पेस के एह विकल्पन के देखे से चार्ज ना होई।",
  "billing.cancel.title": "सब्सक्रिप्शन रद्द करल",
  "billing.cancel.description": "{plan} से अनसब्सक्राइब करल। रद्द करे से राउर भुगतान अवधि के अंत में भविष्य के नवीनीकरण रुक जाई — ई कबो राउर पहुँच एक बेर में खत्म ना करेला।",
  "billing.cancel.yourPlan": "राउर प्लान",
  "billing.cancel.doneTitle": "राउर सब्सक्रिप्शन रद्द हो गइल बा।",
  "billing.cancel.doneWithEnd": "रउआ {endDate} तक पूरा पहुँच रखब। ओह तारीख के बाद राउर {graceDays} दिन के खाली पढ़े वाला ग्रेस अवधि मिली — रउआ अबहूँ लॉग इन करके आपन उत्पाद देख सकत बानी, बाकिर कुछ जोड़, संपादित, डिलीट, स्कैन, इंपोर्ट, एक्सपोर्ट भा बदल ना सकत बानी। {gracePart}",
  "billing.cancel.graceEndsOn": "{date} के 15 दिन के ग्रेस अवधि खत्म होखे के बाद, राउर खाता आ ओकर सभ जानकारी स्थायी रूप से डिलीट हो जाई आ वापस ना मिल सके।",
  "billing.cancel.doneNoEnd": "रउआ आपन भुगतान अवधि के अंत तक पूरा पहुँच रखब। ओकरा बाद, 15 दिन के खाली पढ़े वाला ग्रेस अवधि लागू होई। {wipeSentence}",
  "billing.cancel.refundWindowOpen": "रउआ आपन पहिलका भुगतान चार्ज के 3 दिन के भीतर रद्द कइनी, एह से रउआ ओह पहिलका भुगतान के रिफंड खातिर पात्र हो सकत बानी। रद्द करे से खुद रिफंड जारी ना होला — {contact} से ओकरा के माँगल।",
  "billing.cancel.refundWindowClosed": "रद्द करे से खुद रिफंड जारी ना होला। रिफंड खाली पहिलका सफल भुगतान चार्ज के 3 दिन के भीतर लागू होला, {contact} से माँगल पर।",
