  "billing.cancel.alreadyCanceledWithEnd": "ई {date} के खत्म होई। ओकरा तक राउर पूरा पहुँच बचल रही। ओह तारीख के बाद राउर {graceDays} दिन के खाली पढ़े वाला ग्रेस अवधि मिली, आपन उत्पाद देखे खातिर। {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "ई वर्तमान भुगतान अवधि के अंत में खत्म होई। ओकरा तक राउर पूरा पहुँच बचल रही।",
  "billing.cancel.appStoreNote": "अगर रउआ कबो Google Play भा Apple App Store से सब्सक्राइब करीं, त राउर ओह स्टोर के सब्सक्रिप्शन सेटिंग से ओकरा के रद्द करे के पड़ सकत बा। ई डायलॉग ऐप-स्टोर बिलिंग के रोक ना सकत बा। ऐप अनइंस्टॉल करे भा आपन StockHaven खाता डिलीट करे से स्टोर सब्सक्रिप्शन रद्द ना होई।",
