  "billing.cancel.gracePeriodRest": "रउआ अबहूँ लॉग इन करके आपन उत्पाद देख सकत बानी, ताकि रउआ देख सकीं कि राउर लगे का रहल आ ओकरा के लिख सकीं। बाकी सब बंद बा: कुछ जोड़ल, संपादित, डिलीट, स्कैन, इंपोर्ट, एक्सपोर्ट भा माइग्रेट ना, कवनो सेटिंग ना, कवनो स्टाफ ना।",
