  "billing.dryRun.ariaLabel": "टेस्ट अपग्रेड सिमुलेशन",
  "billing.dryRun.title": "Essentials → Business — अभ्यास सिमुलेशन",
  "billing.dryRun.body": "एह ब्राउज़र में पूरी तरह काल्पनिक रिकॉर्ड इस्तेमाल करके प्रस्तावित अपग्रेड नियम के अभ्यास करल। एह से राउर असली TEST — पजामा पैंट नमूना, राउर वर्तमान Business वर्कस्पेस, Stripe, ट्रायल, सब्सक्रिप्शन भा इन्वेंटरी — कुछो पढ़ल भा बदलल ना जाई।",
  "billing.dryRun.runButton": "स्थानीय अपग्रेड सिमुलेशन चलाईं (कवनो चार्ज ना)",
  "billing.dryRun.passed": "काल्पनिक परिदृश्य आपन स्थानीय जाँच पास कइलस",
  "billing.dryRun.blocked": "काल्पनिक परिदृश्य ब्लॉक भइल",
  "billing.dryRun.example": "उदाहरण: Essentials ($14.99/महीना) → Business ($29.99/महीना), कवनो लागू टैक्स से पहिले।",
  "billing.dryRun.preserved": "उहे सब्सक्रिप्शन बचल रहल, एगो मूल ट्रायल बचल रहल, आ सिमुलेटेड पजामा इन्वेंटरी बदलल ना गइल। उदाहरण ग्राहक Essentials पर रहेला जब तक कवनो असली, प्रदाता-पुष्ट भुगतान नवीनीकरण पहुँच बदले के औचित्य ना देवे।",
  "billing.dryRun.limitations": "स्थानीय सिमुलेशन Stripe सब्सक्रिप्शन बदलाव, भुगतान, वेबहुक, टैक्स-सहित कोट, लाइव सब्सक्रिप्शन भा राउर असली बिजनेस रिकॉर्ड के परीक्षण ना करेला।",
  "billing.dryRun.noRecordsChanged": "कवनो रिकॉर्ड बदलल ना गइल।",
