  "settings.details.address": "पता",
  'settings.details.taxRate': 'हमार टैक्स दर',
  'settings.details.taxRateHint': 'एक बेर सेट करीं। हर नया बिक्री ऑर्डर एही दर से आपन टैक्स खुद भरेला — फेर भी रउआ कवनो एक ऑर्डर के टैक्स बदल सकत बानी।',
  "settings.details.taxMode": "ऑर्डर सभ के आपन टैक्स कइसे मिलेला",
  "settings.details.taxModeFixed": "हमार निश्चित दर",
  "settings.details.taxModeAutomatic": "स्वचालित — ग्राहक के राज्य के हिसाब से",
  "settings.details.taxModeHint": "निश्चित मोड हर नया ऑर्डर पर राउर दर के उपयोग करेला। स्वचालित मोड, जइसे ही राज्य ऑर्डर पर होला, नया ऑर्डर के टैक्स ग्राहक के राज्य के मूल दर से भर देला, अउर राज्य बदले पर फेर से भर देला। ई राज्य के मूल दर हवे — स्थानीय टैक्स अउर जोड़ सकेला। जवना ऑर्डर पर कवनो राज्य न होखे, भा जवन अमेरिका से बाहर के होखे, ऊ ऊपर दिहल राउर निश्चित दर के उपयोग करेला।",
  'settings.details.gs1Prefix': "GS1 कंपनी प्रीफ़िक्स",
  'settings.details.gs1PrefixHint': "खाली तब, जब राउर लगे GS1 से प्रीफ़िक्स के लाइसेंस होखे। एक बेर सेट करीं आ उत्पाद फ़ॉर्म के कोड जनरेटर राउर आपन नंबर से असली खुदरा UPC आ EAN कोड बना सकेला — हर एक खाली एक बेर उपयोग होई आ फेर कबो ना। यदि राउर लगे नइखे त खाली छोड़ दीं; ऐप कबो प्रीफ़िक्स ना गढ़ेला।",
  'settings.details.gs1LearnMore': "GS1 पर नया बानी? अगर रउआ अपने देश में रहत बानी, त अउरी जाने खातिर ओही देश के लिंक के उपयोग करीं; अगर रउआ संयुक्त राज्य अमेरिका में रहत बानी, त GS1 US के लिंक के उपयोग करीं।",
  'settings.details.gs1LearnMoreUs': "GS1 पर नया बानी? अगर रउआ संयुक्त राज्य अमेरिका में रहत बानी, त अउरी जाने खातिर GS1 US के लिंक के उपयोग करीं।",
