  "settings.pastDue.body": "राउर पिछला भुगतान पूरा ना भइल। असफल भुगतान से 14 दिन तक रउरा पूरा उपयोग मिलत रही, जब तक रउरा ओके ठीक ना करीं। अगर ठीक ना भइल, त सदस्यता रद्द हो जाई, कार्यक्षेत्र 15 दिन खातिर खाली देखे योग्य हो जाई, आ फिर खाता आ ओकर सगरी जानकारी हटा दिहल जाई। हटावे से पहिले कवनो समय भुगतान कइला से सगरी वापस आ जाई। अगर रउरा निश्चित नइखीं कि का करे के बा, त theluminousbookshop@outlook.com पर सहायता से संपर्क करीं।",
