  "payroll.dd.steps.body": "1. रउआ के एगो बिजनेस बैंक खाता चाहीं जवन ACH भुगतान भेज सके। 2. हर टीम सदस्य से हस्ताक्षर कइल अधिकार फॉर्म जुटाईं — रद्द चेक नंबर जाँचे में मदद करेला। 3. वेतन वाला दिन से 2-3 बिजनेस दिन पहिले पेरोल भेजीं ताकि पइसा समय पर पहुँचे। 4. ज्यादातर राज्य में टीम सदस्य के लिखित सहमति चाहीं। ई ऐप फॉर्म जुटावेला आ रउआ के कदम-कदम बतावेला — असली पइसा भेजे के काम राउर आपन बैंक से होला।",
