  "recovery.changeIntro": "रउआ भीतर बानी — खाली एक कदम खातिर: आपन खाता खातिर नया ईमेल चुनीं। राउर दुकान, राउर इन्वेंटरी आ राउर टीम पहुँच सभ ओकर साथ चल जाला।",
  "recovery.doneBody": "राउर खाता ईमेल बदल गइल बा आ ई साइन-इन अब फेर से राउर नियमित साइन-इन बा। फेर से स्वागत बा।",
