  "settings.security.title": "सुरक्षा आ अतिरिक्त चाबी",
  "settings.security.description": "राउर अतिरिक्त चाबी के जरूरत पड़े से पहिले सेटअप करीं: अगर रउआ कबो आपन खाता ईमेल के पहुँच खो दीं, त ऊहे बा जइसे रउआ आपन दुकान वापस पाइब।",
  "settings.security.genericError": "कुछ गलत हो गइल। कृपया फेर से कोशिश करीं।",
