  "settings.security.changeEmailDesc": "आपन खाता के नया ईमेल पर ले जाईं। राउर दुकान, इन्वेंटरी, टीम आ इतिहास ओकर साथ चल जाला — आ कवनो नया मुफ्त ट्रायल शुरू ना होला। हर अउर साइन-इन डिवाइस साइन आउट हो जाला।",
