  "crossStore.transferFromLocation": "कवना जगह से",
  "crossStore.transferIntro": "दुनों दोकान राउर ह, एहसे रउआ बिना कवनो निवेदन के स्टॉक सीधा भेज सकत बानी। एगो सामान चुनीं, बताईं केतना आ कहाँ से जाई, आ ऊ दोकान चुनीं जहाँ ऊ पहुँची। दुनों दोकान तुरंत अपडेट हो जाला, आ दुनों एह भेजले के रिकॉर्ड रखेला।",
  "crossStore.transferNoTargets": "अभी राउर अउर कवनो दोकान नइखे — स्टॉक खाली उहे दोकानन के बीच जा सकेला जे राउर ह।",
