  "print.shippingNote": "अगर ऑर्डर में भेजे के पता बा, त ऊ ऑर्डर से भर जाला। रउआ इहाँ जवन लिखब ऊ एक बेर छपेला अउर कबो सहेजल ना जाला।",
  "print.carrier.title": "राउर वाहक के लेबल",
  "print.carrier.desc": "डाक खरच वाहक से कीनीं, जइसे आज कीने लीं — ई ऐप कबो डाक खरच ना बेचेला, एही से जे दाम रउआ दीहीं ऊ हमेशा वाहक के आपन दाम होला। लेबल के फाइल इहाँ सहेजीं आ ई एह ऑर्डर प हमेशा रही: राउर रेकॉर्ड, कुछ हो जाव त हाथ में।",
  "print.carrier.none": "एह ऑर्डर खातिर अबहीं कवनो वाहक लेबल सहेजल नइखे।",
