  "print.style.desc": "आपन दस्तावेज़न के आपन बनाईं। ई पसन राउर इनवॉइस, रसीद, पैकिंग स्लिप, वापसी दस्तावेज़, प्रोडक्ट शीट, गिनती शीट आ पिक लिस्ट के सजावेला — आ राउर बिजनेस खातिर याद रहेला।",
