  "print.style.imageSizeHint": "चौड़ाई पेज के चौड़ाई के ऊ हिस्सा ह जवना के तस्वीर घेरेला; लंबाई छपाई के सबसे जादे ऊँचाई ह। आम आकार खातिर बॉक्स खाली छोड़ दीं।",
  "print.printedAt": "{date} के {time} बजे छपल",
  "print.style.previewText": "तेज़ भूरा लोमड़ी आलसी कुत्ता के ऊपर से कूद जाला। 1234567890",
  "training.lessons.owner-shipping-labels.step1": "प्रिंट सेंटर में दुनो प्लान में शिपिंग लेबल शैली बा: ग्राहक के ऑर्डर चुनीं आ खरीदार के नाम आ पता तथा भेजेवाला के रूप में राउर व्यवसाय वाला 4×6 लेबल छापीं।",
  "training.lessons.owner-shipping-labels.step2": "ई लेबल हर ग्राहक दस्तावेज़ नियर व्हाइट-लेबल बा: एह पर खाली राउर व्यवसाय के नाम होला — एह ऐप के नाम कबो ना — ताकि राउर दुकान से आइल पार्सल राउरे दुकान से आइल लागे।",
  "training.lessons.owner-shipping-labels.step3": "ग्राहक के पता ओकर आखिरी ऑर्डर के बाद 90 दिन तक ओकर ऑर्डर के साथ रखल जाला, आ लेबल ऑर्डर के सहेजल पता से शुरू होला जब ऊ मौजूद होखे; एक बेर के लेबल खातिर छापे के समय टाइप कइल पता वापस सहेजल ना जाला। नाम अभी भी ऑर्डर से भरी जाला ताकि लेबल कागजात से मेल खाव।",
  "training.lessons.owner-shipping-labels.step4": "ई लेबल हर लेबल वाला उहे चार कनेक्शन से छपेला — ब्लूटूथ, वाई-फ़ाई, ईथरनेट आ USB — आ 4×6 थर्मल प्रिंटर एकर मानक आकार ह।",
  "training.lessons.owner-shipping-labels.step5": "डाक खरच वाहक से कीन लेले बानी? एही सेक्शन में रउआ वाहक के लेबल फाइल — PDF, PNG भा JPG — अपलोड कर सके लीं आ ई ऑर्डर प हमेशा सहेजल रही: राउर रेकॉर्ड, कुछ हो जाव त हाथ में। ई आपन सही 4×6 आकार में छपेला। ऐप कबो डाक खरच ना बेचेला, एही से वाहक के दामे एकमात्र दाम बा — आ हमेशा सही दाम।",
  "training.lessons.owner-shipping-labels.title": "ग्राहक ऑर्डर खातिर शिपिंग लेबल",
  "training.lessons.print-shipping-label.step1": "जब कवनो ऑर्डर भेजे खातिर तइयार होखे, प्रिंट सेंटर खोलीं, शिपिंग लेबल शैली चुनीं आ फिर ग्राहक के ऑर्डर चुनीं। खरीदार के नाम ऑर्डर से भर जाला।",
  "training.lessons.print-shipping-label.step2": "ऊ पता जाँच लीं जहाँ पार्सल जा रहल बा। जब ऑर्डर में ग्राहक के पता होखे — ओकर आखिरी ऑर्डर के बाद 90 दिन तक रखल — त ऊ रउरा खातिर भर जाला; छापे के समय टाइप कइल पता वापस सहेजल ना जाला, एह से छापे से पहिले पिन कोड आ आखिरी लाइन के ध्यान से जाँचीं।",
  "training.lessons.print-shipping-label.step3": "राउर व्यवसाय के नाम भेजेवाला के रूप में ऊपर छपेला। यदि रउआ चाहत बानी कि राउर पता भी लेबल पर होखे, त ओके भेजेवाला के पता वाला बॉक्स में लिखीं; ना देखावे के चाहीं त खाली छोड़ दीं।",
  "training.lessons.print-shipping-label.step4": "4×6 लेबल पर छापीं — थर्मल लेबल प्रिंटर आमतौर पर ठीक रहेला — भा ब्राउज़र के प्रिंट बटन से कवनो प्रिंटर पर। लेबल के पार्सल पर सपाट चिपकाईं, जहाँ ऊ किनारा पर ना मु़ड़े।",
  "training.lessons.print-shipping-label.step5": "अगर डाक खरच वाहक से किनाइल बा, त एकरा बदले ओकर लेबल फाइल ऑर्डर प सहेजीं: राउर वाहक के लेबल सेक्शन में वाहक के दिहल PDF, PNG भा JPG अपलोड करीं। ई राउर रेकॉर्ड के रूप में ऑर्डर प रहेला आ आपन सही 4×6 आकार में छपेला — आ ऐप के आपन पता वाला लेबल हमेशा उहाँ बा, जब रउआ ओकरा के इस्तेमाल करे के चाहब।",
  "training.lessons.print-shipping-label.title": "शिपिंग लेबल छापीं",
  "pos.provider.clover": "Clover",
