  "pos.clover.help": "Clover जोड़ीं आ गल्ला पर हर बिक्री ओकर आइटम के इहाँ स्टॉक से अपने आप निकाल देला — दिन के अंत में कुछ टाइप करे के नइखे।",
  "pos.clover.connect": "Clover जोड़ीं",
  "pos.clover.notConfigured": "Clover कनेक्शन अबहिन चालू नइखे भइल। नीचे वाला CSV इंपोर्ट आज काम करेला।",
