  "settings.install.description": "Luminous StockHaven के एह डिवाइस पर पाईं — भा अगर ई गुम हो जाव त एकरा के वापस पाईं। ई सीधे एही वेबसाइट से इंस्टॉल होला (ऐप स्टोर के ज़रूरत नइखे) आ राउर होम स्क्रीन से पूरा स्क्रीन में खुलेला।",
