  "settings.policies.ownerDescription": "रउरा स्टोर, रउरा नियम। अपना स्टोर के नीति अउर अपना नियम व शर्त इहाँ लिखीं — ओके लिखीं, चाहे फाइल अपलोड करीं। टीम के हर नया सदस्य शुरुआत में ओके एक बेर देखेला, अउर रउरा पूरा टीम ओके इहाँ कबहुँ पढ़ सकेला। ओके खाली रउरे बदल सकेनी।",
