  "staffWelcome.policiesIntro": "शुरू करे से पहिले: रउरा स्टोर के नीति अउर शर्त, मालिक द्वारा लिखल।",
  "plansLib.includes.storePolicies": "सेटिंग्स में रउरा स्टोर के आपन नीति अउर शर्त, रउरा पूरा टीम के पढ़े खातिर",
  "apiErrors.businessPoliciesOwnerOnly": "ए स्टोर के नीति अउर शर्त खाली मालिके बदल सकेला।",
  "apiErrors.policyFileInvalid": "25 MB से छोट PDF, टेक्स्ट, Word चाहे OpenDocument फाइल भेजीं।",
  "apiErrors.policyTextTooLong": "ओ दस्तावेज इहाँ लिखे खातिर बहुत लमहर बा। ओकरे बदला रउरा ओके फाइल के रूप में अपलोड कर सकेनी।",
  "training.lessons.owner-store-policies.title": "रउरा स्टोर के नीति अउर शर्त",
  "training.lessons.owner-store-policies.step1": "सेटिंग्स खोलीं अउर स्टोर के नीति व शर्त वाला कार्ड खोजीं। ओमें दू गो दस्तावेज बा: रउरा स्टोर के नीति — रउरा स्टोर खातिर घर के नियम — अउर रउरा नियम व शर्त।",
  "training.lessons.owner-store-policies.step2": "हर दस्तावेज ओहिजा लिखल जा सकेला, चाहे फाइल के रूप में अपलोड कइल जा सकेला (PDF, टेक्स्ट, Word चाहे OpenDocument, 25 MB तक)। एक चाहे दूसर: लिखल सहेजला से फाइल बदल जाला, अउर फाइल अपलोड कइला से लिखल बदल जाला। दस्तावेज हटावला से ऊ साफ हो जाला।",
  "training.lessons.owner-store-policies.step3": "रउरा टीम दुनों दस्तावेज एक बेर देखेला, उनकर पहिला शुरुआत में उनकर स्वागत पेज पर, अउर ओके कबहुँ अपना सेटिंग्स में पढ़ सकेला। रउरा टीम खातिर ऊ खाली पढ़े खातिर बा — ओके खाली रउरे लिख चाहे बदल सकेनी।",
  "training.lessons.owner-store-policies.step4": "हर व्यवसाय अपना दस्तावेज अपना लगे राखेला: रउरा इहाँ जवन लिखेनी ऊ खाली एही स्टोर के ह अउर कबो दूसरा व्यवसाय में ना देखाई देला। Luminous StockHaven के आपन नियम अउर नीति सेटिंग्स में रउरा दस्तावेज के संगे रहेला, अउर ओहू के हर आदमी पढ़ सकेला।",
  "training.lessons.welcome-basics.step5": "रउरा स्टोर के नीति अउर शर्त रउरा स्वागत पेज पर एक बेर देखावल जाला, अउर ऊ सेटिंग्स में रहेला, जहाँ रउरा ओके कबहुँ पढ़ सकेनी।",
  "apiErrors.policyDocNotFound": "ऊ दस्तावेज दुनों में से एक नइखे।",
  "apiErrors.policyFileNotFound": "ऊ दस्तावेज खातिर कवनो फाइल सहेजल नइखे गइल।",
