  "staff.memberDialog.trainingAccessHint": "स्टोर के नीति आ शर्त पढ़ल सबके खातिर बा। ई टिक ओह क्विज़ ट्रेनिंग के सौंपेला जवन मालिक सेटिंग्स में हर दस्तावेज़ के बगल में बनावेला।",
