  "training.policy.read": "दस्तावेज़",
  "training.policy.reviewWaiting": "राउर लिखल जवाब में से एक मालिक के देखे खातिर बा। ट्रेनिंग पूरा गिनल जाला जब तक मालिक एकरा के वापस ना भेजे।",
  "training.policy.rightPick": "ई सही बा।",
  "training.policy.score": "स्कोर: {score}%",
  "training.policy.sectionHelp": "राउर मालिक ई दस्तावेज़ राउर स्टोर खातिर लिखले बा। हर एक के पढ़ीं, फिर मालिक के सवाल के जवाब दीं।",
