  "profile.title": "राउर प्रोफ़ाइल फोटो",
  "profile.ownerDesc": "राउर फोटो आ ऊ नाम जवन से राउर टीम रउआ के जानत बा। राउर आपन फोटो तुरते देखाई देला — कउनो मंजूरी के जरूरत नइखे।",
  "profile.memberDesc": "राउर फोटो राउर नाम के बगल में तब देखाई देला जब मालिक ओकरा के मंजूर कर देस। तब ले खाली राउर नाम के पहिला अक्षर देखाई देला।",
  "profile.stateApproved": "ई ऊ फोटो बा जवन राउर टीम देखत बा।",
