  "profile.stateChangePending": "राउर नया फोटो मालिक के मंजूरी के इंतजार करत बा। तब ले राउर वर्तमान फोटो बनल रही।",
  "profile.choose": "फोटो चुनीं",
  "profile.change": "फोटो बदलीं",
  "profile.declinedFirst": "राउर फोटो मंजूर ना भइल। कृपया कउनो दोसर फोटो चुनीं।",
  "profile.declinedChange": "राउर फोटो मंजूर ना भइल — बाकिर राउर दोसर फोटो अभी भी रउआ के पास बा। अगर रउआ ओकरा के बदले के चाहत बानी, त कउनो दोसर फोटो आज़माईं।",
  "profile.approvedNote": "मालिक राउर फोटो मंजूर कर दिहले बाड़न।",
  "profile.toastOwnerLive": "राउर फोटो अब लाइव बा।",
  "profile.toastSent": "मंजूरी खातिर मालिक के पास भेज दिहल गइल।",
  "profile.toastFailed": "ऊ काम ना कइलस — कृपया फेर से कोशिश करीं।",
  "profile.nameLabel": "राउर नाम",
  "profile.nameHint": "ई नाम हर जगह मालिक शब्द के जगह ले लेला — राउर फोटो के बगल में, संदेश में, आ राउर टीम के स्क्रीन पर। मालिक कहाए खातिर एकरा के खाली छोड़ दीं।",
  "profile.nameSave": "नाम सहेजीं",
  "profile.nameSaved": "अब रउआ {name} के नाम से जानल जाईं।",
  "profile.nameCleared": "राउर नाम साफ़ कर दिहल गइल बा — रउआ फेर से मालिक कहाईं।",
  "profile.approvalsTitle": "राउर मंजूरी के इंतजार करत फोटो",
  "profile.approvalsDesc": "टीम के कउनो फोटो तब ले कहऽ ना देखाई देला जब ले रउआ ओकरा के मंजूर ना कर दीं। अगर रउआ ओकरा के मंजूर ना करीं, त ऊ आदमी से दोसर फोटो चुने के कहल जाला।",
