  "profile.declinedToast": "फोटो मंजूर ना भइल — उनकरा से दोसर फोटो चुने के कहल जाई।",
  "plansLib.includes.profilePhotos": "राउर पूरा टीम खातिर प्रोफ़ाइल फोटो, मालिक द्वारा मंजूर",
  "apiErrors.notFound.photoFound": "फोटो ना मिलल।",
  "apiErrors.profileOwnerNameOnly": "खाली व्यवसाय के मालिक ही मालिक के नाम सेट कर सकेला।",
  "apiErrors.profilePhotosApproveOwnerOnly": "खाली व्यवसाय के मालिक ही टीम के फोटो मंजूर कर सकेला।",
  "apiErrors.profilePhotosNoneWaiting": "ऊ टीम सदस्य के कउनो फोटो मंजूरी के इंतजार नइखे करत।",
  "apiErrors.profileOwnerNameTooLong": "आपन नाम 80 अक्षर भा ओसे कम में राखीं।",
  "training.lessons.your-profile-photo.title": "राउर प्रोफ़ाइल फोटो",
  "training.lessons.your-profile-photo.step1": "राउर फोटो राउर नाम के बगल में ऐप के ऊपर, स्टाफ़ पेज पर, आ राउर संदेश के बगल में देखाई देला — जब मालिक ओकरा के मंजूर कर देस। तब ले खाली राउर नाम के पहिला अक्षर देखाई देला।",
  "training.lessons.your-profile-photo.step2": "सेटिंग्स खोलीं आ आपन प्रोफ़ाइल फोटो खोजीं। आपन एगो फोटो चुनीं आ ओकरा के भेजीं। ई मंजूरी खातिर मालिक के पास जाला — इंतजार के दौरान ई कहऽ ना देखाई देला।",
  "training.lessons.your-profile-photo.step3": "जब मालिक ओकरा के मंजूर कर देस, त राउर घंटी बाजेला आ राउर फोटो देखाई देवे लागेला। अगर ई मंजूर ना होखे, त एगो अलग फोटो चुनीं आ ओकरे बदले ओकरा के भेजीं।",
  "training.lessons.your-profile-photo.step4": "आपन फोटो बदलल भी ओही तरह काम करेला: नया वाला मंजूरी के इंतजार करेला, आ राउर वर्तमान फोटो तब ले आपन जगह बनल रहेला जब ले नया वाला मंजूर ना हो जाव। अगर कउनो बदलाव मंजूर ना होखे, त रउआ आपन दोसर फोटो राख लेब।",
  "training.lessons.owner-profile-photos.title": "प्रोफ़ाइल फोटो आ राउर नाम",
  "training.lessons.owner-profile-photos.step1": "हर आदमी के फोटो ओकर नाम के बगल में ऐप के ऊपर, राउर स्टाफ़ पेज पर, आ ओकर संदेश के बगल में देखाई देला। टीम के सदस्य के फोटो तब ले कहऽ ना देखाई देला जब ले रउआ ओकरा के मंजूर ना कर दीं — मंजूरी खाली राउर बा, आ केहू आपन फोटो खुद मंजूर ना कर सकेला।",
  "training.lessons.owner-profile-photos.step2": "जब केहू फोटो भेजेला, त राउर घंटी बाजेला। ओकरा के देखे खातिर स्टाफ़ पेज खोलीं, फेर मंजूर करीं भा मंजूर मत करीं चुनीं। अगर रउआ ओकरा के मंजूर ना करीं, त ऊ आदमी से दोसर फोटो चुने के कहल जाला।",
  "training.lessons.owner-profile-photos.step3": "अगर केहू आदमी आपन फोटो बदलेला, त नया वाला ओही तरह राउर मंजूरी के इंतजार करेला। ओकर वर्तमान फोटो इंतजार के दौरान आपन जगह बनल रहेला — आ अगर रउआ बदलाव मंजूर ना करीं त बनल रहेला।",
  "training.lessons.owner-profile-photos.step4": "राउर आपन फोटो के कउनो मंजूरी के जरूरत नइखे: एकरा के सेटिंग्स में, राउर प्रोफ़ाइल फोटो के नीचे सेट करीं। ओही कार्ड में राउर नाम भी रहेला — ऊहाँ सेट कइल नाम हर ऊ जगह मालिक शब्द के जगह ले लेला जहाँ राउर टीम ओकरा के देखत बा, ऐप में आ संदेश में।",
  "payroll.dd.corrected": "सुधारल गइल फॉर्म",
  "payroll.dd.correctedDone": "राउर सुधारल विवरण मालिक लगे भेज दिहल गइल।",
  "payroll.dd.correctionNotice": "मालिक राउर फॉर्म राउरे लगे वापस भेजले बाड़न ताकि रउआ एकरा के सुधार सकीं। हर अंक जाँचीं, हस्ताक्षर करीं आ फिर से भेजीं।",
  "payroll.dd.correctionWaiting": "वापस भेजल गइल — उनकर सुधारल फॉर्म के इंतजार बा",
  "payroll.dd.fixHelp": "अगर कवनो अंक गलत बा, त आपन विवरण सुधारीं आ फॉर्म फिर से भेजीं। राउर नया हस्ताक्षरित फॉर्म पुरान वाला के जगह ले लेला, आ मालिक के बतावल जाला कि एकरा के सुधारल गइल रहे।",
