  "payroll.dd.signHelp": "आपन नाम लिखीं, फिर चुनीं कि राउर हस्ताक्षर कइसे देखाई। ईहे राउर इलेक्ट्रॉनिक हस्ताक्षर ह — ई राउर सीधा जमा फॉर्म पर ठीक ओइसहीं लगावल जाला जइसे इहाँ देखावल गइल बा।",
