  "training.lessons.owner-dd-setup.step5": "जवन पहुँचेला ऊ एगो मुहरबंद, हस्ताक्षरित फॉर्म होला: पेरोल में ऊ व्यक्ति के पंक्ति से रउआ एकरा के खोल के पूरा नंबर पढ़ सकेनी, प्रिंट कर सकेनी भा एगो प्रति सहेज सकेनी — रउआ एकरा के कबो संपादित ना कर सकेनी। अगर कवनो नंबर गलत लागे, त फॉर्म वापस भेजीं: ऊ व्यक्ति खुद एकरा के सुधारेला आ फिर से हस्ताक्षर करेला, ओकर सुधारल फॉर्म पुरान वाला के जगह ले लेला, आ पिछला फॉर्म आपन बदली के तारीख के साथ रिकॉर्ड में रह जाला।",
