  "staff.memberDialog.clockAccessHint": "खाली प्रबंधक लोग खातिर — दू गो अलग-अलग टिक। घड़ी बोर्ड अउर छूटल घड़ी-आउट एह प्रबंधक के टीम के घड़ी प्रविष्टि देखे अउर स्टाफ पेज से समय प्रविष्टि सुधारे देला। कॉल-इन एह प्रबंधक के कॉल-इन विंडो खोले देला, कवनो के तब काम करे दिहल जब ओकर शिफ्ट तय ना होखे। ई टिक सभ स्टाफ खातिर कुछ ना करेला।",
