  "apiErrors.clockGate.notScheduled": "अभी राउर काम तय नइखे, अउर राउर खातिर कवनो कॉल-इन विंडो खुलल नइखे।",
  "apiErrors.clockAdmin.callinsNotGranted": "खाली मालिक, चाहे ऊ प्रबंधक जवना पर मालिक कॉल-इन खातिर भरोसा कइले बा, ई कर सकेला।",
  "apiErrors.clockAdmin.boardNotGranted": "खाली मालिक, चाहे ऊ प्रबंधक जवना पर मालिक घड़ी बोर्ड अउर छूटल घड़ी-आउट खातिर भरोसा कइले बा, ई कर सकेला।",
  "apiErrors.clockAdmin.ownerOnlyForManager": "प्रबंधक के कॉल-इन अउर समय प्रविष्टि खाली मालिक ही संभाल सकेला।",
  "apiErrors.clockFix.outBeforeIn": "क्लॉक-आउट के समय क्लॉक-इन के समय के बाद होखे के चाहीं।",
  "apiErrors.clockFix.breakOutside": "विराम के समय क्लॉक-इन अउर क्लॉक-आउट समय के बीच होखे के चाहीं।",
  "apiErrors.clockFix.invalidTime": "हर समय के मान्य तारीख अउर समय के रूप में भेजीं।",
  "apiErrors.notFound.timeEntryFound": "समय प्रविष्टि ना मिलल।",
  "training.lessons.mgr-clock-callin.title": "कॉल-इन अउर घड़ी सुधार",
  "training.lessons.mgr-clock-callin.step1": "मालिक प्रबंधक के दू गो अलग-अलग टिक दे सकेला। कॉल-इन रउआ के स्टाफ सदस्य खातिर कॉल-इन विंडो खोले देला, अउर घड़ी बोर्ड अउर छूटल घड़ी-आउट रउआ के टीम के घड़ी बोर्ड देखे अउर स्टाफ पेज से समय प्रविष्टि सुधारे देला। हर टिक अपनही काम करेला — प्रबंधक एगो के बिना दूसरा के रख सकेला।",
  "training.lessons.mgr-clock-callin.step2": "कॉल-इन विंडो कवनो आदमी के तब साइन इन अउर क्लॉक इन करे देला जब कवनो शिफ्ट ओके ना ढकत होखे। एकरा के स्टाफ पेज पर, कॉल-इन अउर छूटल क्लॉक-आउट कार्ड से खोलीं।",
  "training.lessons.mgr-clock-callin.step3": "विंडो तब ले खुलल रहेला जब ले ऊ आदमी क्लॉक आउट ना करे — फिर साइन-आउट से पहिले के सामान्य 10-मिनट के छूट आवेला — या जब ले रउआ या मालिक एकरा के पहिले बंद ना कर दीं। कुछुओ एकरा के अपने आप बंद ना करेला।",
  "training.lessons.mgr-clock-callin.step4": "जब कवनो क्लॉक आउट करे के भुला जाला, त तय शिफ्ट खतम होते ही ओकर प्रविष्टि स्टाफ पेज अउर पेरोल में चिन्हित हो जाला, अउर रउआ अउर मालिक के सूचना मिलेला। प्रविष्टि तब ले गिनत रहेला जब ले सुधारल ना जाय।",
  "training.lessons.mgr-clock-callin.step5": "प्रविष्टि के स्टाफ पेज से सुधारीं: क्लॉक-इन, क्लॉक-आउट अउर विराम के समय तय करीं। प्रबंधक खाली स्टाफ के प्रविष्टि सुधारेला — प्रबंधक के अपने प्रविष्टि मालिक सुधारेला।",
  "staffLib.perm.staffDocuments": "स्टाफ दस्तावेज़",
  "staffLib.area.documentsAccess": "स्टाफ दस्तावेज़",
  "staff.memberDialog.documentsAccessHint": "खाली मैनेजर लोग खातिर — एह टिक के साथ, ई मैनेजर स्टाफ सदस्य लोग के दस्तावेज़ फाइल खोल सकेला: हर आदमी खातिर रखल कागज़ात, जइसे W-4 फॉर्म, नौकरी के आवेदन आ पहचान पत्र के कॉपी। पहिले रउआ से पुष्टि माँगल जाई — एह फाइल सभ में सामाजिक सुरक्षा नंबर आ जन्म तिथि होला। ई टिक स्टाफ खातिर कुछ ना करेला।",
  "staff.documentsWarning.body": "ई आदमी रउआ स्टाफ सदस्य लोग के बारे में गोपनीय जानकारी देख सकेला, जवना में सामाजिक सुरक्षा नंबर आ जन्म तिथि शामिल बा।",
  "staff.documentsWarning.confirm": "हँ, हम बुझत बानी",
  "staff.documents.title": "स्टाफ दस्तावेज़",
  "staff.documents.desc": "ऊ कागज़ात जवन रउआ हर आदमी खातिर राखत बानी — W-4 फॉर्म, नौकरी के आवेदन, टैक्स फॉर्म, पहचान पत्र के कॉपी। खाली रउआ, आ ऊ मैनेजर जवना के रउआ स्टाफ दस्तावेज़ टिक देब, ई फाइल सभ खोल सकेला।",
