  "nav.xstoreMessages": "सभ दोकानन में संदेश",
  "plansLib.businessIncludes.xstoreMessages": "सभ दोकानन में संदेश — रउआ पूरा टीम, सभ कारोबारन में",
  "xstore.title": "सभ दोकानन में संदेश",
  "xstore.help": "एह खाता पर के सभे लोग, रउआ सभ कारोबारन में, एके इनबॉक्स में। एहिजा केहू के भी संदेश भेजीं — लिख के भा आवाज़ में, पहुँचल आ पढ़ल के निशान के साथ। रउआ दोकान के भीतर वाला संदेश जइसे बा, ओइसहीं रही।",
  "xstore.empty": "अभी ले कवनो बातचीत नइखे। नया संदेश से एगो शुरू करीं।",
  "xstore.noPeople": "अभी संदेश भेजे खातिर केहू दोसर नइखे। लोग एहिजा तब देखाई दिहें जब ऊ रउआ कवनो कारोबार में शामिल होके साइन इन कर लिहें।",
  "xstore.deliveredLabel": "पहुँच गइल",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "सभ दोकानन में संदेश बिज़नेस प्लान के हिस्सा ह।",
  "apiErrors.invalidValue.personNotPartAccount": "ऊ आदमी एह खाता के हिस्सा नइखे।",
  "training.lessons.owner-xstore-messages.title": "रउआ दोकानन में संदेश, मालिकन खातिर",
  "training.lessons.owner-xstore-messages.step1": "सभ दोकानन में संदेश, संदेश से अलग दोसर इनबॉक्स ह। संदेश ओह दोकान खातिर ह जवना में रउआ खड़ा बानी; ई दरवाजा रउआ खाता पर के सभे लोग तक पहुँचेला, रउआ हर कारोबार में — पाँच गो ले।",
  "training.lessons.owner-xstore-messages.step2": "मेनू से सभ दोकानन में संदेश खोलीं आ सूची में के केहू के साथ बातचीत शुरू करीं। सूची में रउआ सभ कारोबारन के हर टीम सदस्य देखाई देला जे साइन इन कइले बा, ओह दोकानन के साथ जवना में ऊ काम करेला।",
  "training.lessons.owner-xstore-messages.step3": "फोटो साथ-साथ चलेला: हर आदमी आपन मंज़ूर प्रोफ़ाइल फोटो देखावेला, भा जब फोटो नइखे त आपन नाँव के पहिला अक्षर। हर संदेश में ओकर भेजल गइल तारीख आ समय रहेला।",
  "training.lessons.owner-xstore-messages.step4": "आपन संदेश के नीचे रउआ देख सकीला कि संदेश पहुँचला पर पहुँच गइल, आ जब दोसर आदमी बातचीत खोलेला त पढ़ लिहलस। आवाज़ वाला नोट एहिजो काम करेला, ठीक संदेश में जइसन।",
  "training.lessons.owner-xstore-messages.step5": "एहिजा के बातचीत ओह दूनो लोग खातिर निजी ह जवना बीच ऊ बा। रउआ दोकान के भीतर वाला संदेश पर नजर दोकानन के पार नइखे पहुँचत।",
  "training.lessons.mgr-xstore-messages.title": "रउआ दोकानन में संदेश, मैनेजरन खातिर",
  "training.lessons.mgr-xstore-messages.step1": "सभ दोकानन में संदेश एह खाता पर के सभे लोग तक पहुँचेला, हर कारोबार में — खाली ओह दोकान तक ना जवना में रउआ खड़ा बानी। ई मेनू में बा, संदेश से अलग।",
  "training.lessons.mgr-xstore-messages.step2": "सूची से बातचीत शुरू करीं: हर टीम सदस्य जे साइन इन कइले बा ओहिजा बा, ओकर नाँव के बगल में ओह दोकानन के साथ जवना में ऊ काम करेला।",
  "training.lessons.mgr-xstore-messages.step3": "लिख के भेजीं, भा आवाज़ वाला नोट रिकॉर्ड करीं। आवाज़ वाला नोट भेजे से पहिले, रउआ ओके सुन सकीला, फेंक सकीला, भा भेज सकीला — ठीक संदेश में जइसन।",
  "training.lessons.mgr-xstore-messages.step4": "रउआ संदेश जब पहुँचेला त पहुँच गइल देखावेला आ जब दोसर आदमी बातचीत खोलेला त पढ़ लिहलस। हर नाँव के बगल के फोटो ओह आदमी के मंज़ूर प्रोफ़ाइल फोटो ह।",
  "training.lessons.staff-xstore-messages.title": "रउआ दोकानन में संदेश",
  "training.lessons.staff-xstore-messages.step1": "सभ दोकानन में संदेश ऊ जगह ह जहाँ रउआ एह खाता पर के केहू के भी, मालिक के कवनो भी कारोबार में, पहुँच सकीला — दोसर दोकान खातिर सवाल अब इंतज़ार ना करी।",
  "training.lessons.staff-xstore-messages.step2": "मेनू से खोलीं, आदमी चुनीं, आ लिखीं। जेकरा रउआ जरूरत बा ऊ सूची में नइखे, त ऊ अभी साइन इन नइखे कइले — ऊ जइसे करी, ओइसे देखाई दी।",
  "training.lessons.staff-xstore-messages.step3": "रउआ एहिजो आवाज़ वाला नोट भेज सकीला: रिकॉर्ड करीं, सुन के देखीं, फिर भेजीं भा फेंक दीं। हर संदेश ओकर भेजल गइल तारीख आ समय देखावेला।",
  "training.lessons.staff-xstore-messages.step4": "जब रउआ संदेश भेजीला, ऊ पहुँचला पर पहुँच गइल देखावेला, आ जब दोसर आदमी बातचीत खोलेला त पढ़ लिहलस। बातचीत रउआ आ दोसर आदमी खातिर निजी ह।",
