  "exportsLib.restaurantLedger.description": "प्राप्त खरीदारी, बर्बादी, स्टाफ खाना आ रेसिपी घटाव एक खाता में: खंड, तारीख, सामान, मात्रा, इकाई लागत, कुल लागत आ संदर्भ।",
