  "storefronts.ebayDesc": "आपन eBay स्टोरफ्रंट एक बेर कनेक्ट करीं। जब eBay पर कवनो आइटम बिकाला, त ओकर गिनती इहाँ अपने आप घट जाला, आ बिक्री राउर आवाजाही में दर्ज हो जाला — ठीक ओसही जइसे ऊ स्कैन क के बाहर निकालल गइल होखे। बिक्री खाली एके दिशा में जाला: eBay से ऐप में।",
