  "storefronts.matchingIntro": "{count} बिकाइल आइटम के अभी कवनो प्रोडक्ट से मेल नइखे भइल। हर एक के ओकर प्रोडक्ट से लिंक करीं आ ओकर रोकल गइल बिक्री अपने आप दर्ज हो जाला — इंतजार करत समय कुछो नइखे गुम होत।",
