  "training.lessons.owner-own-training.step1": "प्रशिक्षण पृष्ठ के बिल्कुल अंत में अपन खुद के प्रशिक्षण जोड़ल जाव वाला बॉक्स बा। ओके खोलल जाव, नया प्रशिक्षण शुरू कइल जाव, आ ओके शीर्षक दिहल जाव — राउर सुरक्षा नियम, राउर सावधानी, राउर काम करे के तरीका।",
  "training.lessons.owner-own-training.step2": "प्रशिक्षण खुद बॉक्स में अपन शब्दन में लिखल जाव, या एकर बदले ओके फाइल के रूप में अपलोड कइल जाव — PDF, टेक्स्ट, Word या OpenDocument फाइल। टाइप कइल शब्द सहेजल फाइल के जगह ले लेला, आ फाइल टाइप कइल शब्दन के जगह ले लेला।",
  "training.lessons.owner-own-training.step3": "ओकर नीचे ओकर प्रश्नोत्तरी बनावल जाव: जेतना सवाल चाहीं, बहुविकल्पी आ लिखित-उत्तर स्वतंत्र रूप से मिलल। लिखित सवाल खातिर, ऊ उत्तर लिखल जाव जे रउआ अपेक्षा करेनी; बहुविकल्पी खातिर, सही वाला प निशान लगावल जाव।",
  "training.lessons.owner-own-training.step4": "उत्तीर्ण रेखा तय कइल जाव, आ चुनल जाव कि लिखित उत्तर कइसे जाँचल जाई: राउर उत्तर-कुंजी से लगभग शब्दशः जाँचल जाई, या रउआ लगे भेजल जाई जेह से रउआ उत्तीर्ण चिन्हित करीं या वापस भेजीं। फिर ठीक-ठीक निशान लगावल जाव कि टीम के कवन सदस्य ई प्रशिक्षण लेत बाड़न — खाली ऊहे लोग एके देखेलन।",
  "training.lessons.owner-own-training.step5": "रउआ जे भी प्रशिक्षण सहेजेनी ऊ बॉक्स में अपन सवालन, रेखा आ निशानन के साथ अलग खड़ा रहेला, आ रउआ जेतना चाहीं जोड़ सकत बानी। परिणाम हर प्रशिक्षण के नीचे बॉक्स में आवेला; कवनो प्रशिक्षण तभी पूरा गिनल जाला जब सर्वर उत्तीर्ण प्रयास के जाँच ले लेला — या, मूल्यांकन मोड में, जब रउआ ओके उत्तीर्ण चिन्हित करेनी।",
