  "training.lessons.owner-barcode-pool.step1": "कुछ सामान के आपन बारकोड ना होला — हाथ से बनावल चीज, रउआ आपन किताब वाला झोरा, जवन कुछ रउआ खुद बनावेनी भा जोड़ेनी। प्रिंट सेक्शन में बारकोड बनाईं दुआर प्रोडक्ट के होखे से पहिले कोड बनावेला।",
  "training.lessons.owner-barcode-pool.step2": "बताईं केतना चाहीं — कवनो सीमा नइखे — आ ऐप रउआ बिजनेस के बारकोड पूल में ओतने नया कोड ढाली। ऊ खाली रउआ बिजनेस के हवें, कबो दू बेर ना दियालें, आ ओके बनावे से ना प्रोडक्ट बनेला ना स्टॉक।",
  "training.lessons.owner-barcode-pool.step3": "जइसे ऊ बन जास, चुनीं: अभी लेबल के रूप में छापीं, भा बाद में छापे खातिर PDF के रूप में सेव करीं। दुनो हालत में कोड पूल में बाड़ें, आ छापल लेबल पूल से बिल्कुल मेल खालें।",
  "training.lessons.owner-barcode-pool.step4": "हर सामान बनावत घरी ओह पर एक लेबल चिपकाईं। बिना इस्तेमाल कोड बस पूल में इंतजार करेलें — कवनो जल्दी नइखे आ ऊ खतम ना होखेलें।",
  "training.lessons.owner-barcode-pool.step5": "जब लेबल लागल सामान बाद में स्कैन होला, त ऐप आपन छापल कोड के पहचानेला आ कोड पहिले से भरल के साथ प्रोडक्ट जोड़े के पेशकश करेला। जुड़ गइला के बाद, ऊ कोड ओह प्रोडक्ट के कोड बन जाला आ कवनो अउर नियर स्कैन होला।",
